-- ============================================
-- LUMA — Thème 3 : MOYEN 1/3 x4 — Un entretien technique complet
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "Let''s start with a technical question — how would you approach optimizing a slow database query?", "text_fr": "Commençons par une question technique — comment aborderiez-vous l''optimisation d''une requête de base de données lente ?", "choices": [{"text": "I''d start by analyzing the query execution plan to find bottlenecks.", "text_fr": "Je commencerais par analyser le plan d''exécution de la requête pour trouver les goulots d''étranglement.", "next": "n2"}, {"text": "First, I''d check if proper indexes exist on the queried columns.", "text_fr": "D''abord, je vérifierais si des index appropriés existent sur les colonnes interrogées.", "next": "n2"}]}, "n2": {"speaker": "recruiter", "text": "Good approach. What if adding an index doesn''t fully solve it?", "text_fr": "Bonne approche. Et si ajouter un index ne résout pas complètement le problème ?", "choices": [{"text": "I''d look into restructuring the query itself, maybe splitting it up.", "text_fr": "Je regarderais restructurer la requête elle-même, peut-être en la divisant.", "next": "n3"}, {"text": "I might consider caching frequent results to reduce database load.", "text_fr": "Je pourrais envisager de mettre en cache les résultats fréquents pour réduire la charge.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "Solid thinking. Let''s shift to a behavioral question — tell me about a time you disagreed with a manager.", "text_fr": "Bon raisonnement. Passons à une question comportementale — parlez-moi d''une fois où vous étiez en désaccord avec un manager.", "choices": [{"text": "I once disagreed on a project timeline and proposed data to support my view.", "text_fr": "J''étais une fois en désaccord sur un calendrier de projet et j''ai proposé des données pour appuyer mon point de vue.", "next": "n4"}, {"text": "I disagreed on a technical approach, but ultimately trusted their experience.", "text_fr": "J''étais en désaccord sur une approche technique, mais j''ai finalement fait confiance à leur expérience.", "next": "n4b"}]}, "n4": {"speaker": "recruiter", "text": "How did that conversation go?", "text_fr": "Comment cette conversation s''est-elle passée ?", "choices": [{"text": "They appreciated the data and we adjusted the timeline together.", "text_fr": "Ils ont apprécié les données et on a ajusté le calendrier ensemble.", "next": "n5"}]}, "n4b": {"speaker": "recruiter", "text": "Was that difficult, deferring on something you disagreed with?", "text_fr": "C''était difficile, de céder sur quelque chose avec lequel vous étiez en désaccord ?", "choices": [{"text": "A little, but I trusted their judgment given their experience.", "text_fr": "Un peu, mais j''ai fait confiance à leur jugement vu leur expérience.", "next": "n5"}, {"text": "Yes, but it turned out to be the right call in the end.", "text_fr": "Oui, mais ça s''est avéré être la bonne décision au final.", "next": "n5"}]}, "n5": {"speaker": "recruiter", "text": "Good, that shows maturity. Now — this is a tricky one. What''s your biggest weakness?", "text_fr": "Bien, ça montre de la maturité. Maintenant — celle-ci est délicate. Quel est votre plus grand point faible ?", "choices": [{"text": "I tend to over-prepare for meetings, which sometimes costs me time.", "text_fr": "J''ai tendance à trop me préparer pour les réunions, ce qui me coûte parfois du temps.", "next": "n6"}, {"text": "I used to struggle with delegating, though I''ve worked hard on it.", "text_fr": "J''avais du mal à déléguer, même si j''ai beaucoup travaillé là-dessus.", "next": "n6"}]}, "n6": {"speaker": "recruiter", "text": "That''s a genuine answer, I appreciate that. Any technical tools you''re less confident in?", "text_fr": "C''est une réponse sincère, j''apprécie. Des outils techniques dans lesquels vous êtes moins à l''aise ?", "choices": [{"text": "I''m still developing my skills with cloud infrastructure, but learning fast.", "text_fr": "Je développe encore mes compétences en infrastructure cloud, mais j''apprends vite.", "next": "n7"}, {"text": "Honestly, I haven''t had much exposure to machine learning tools yet.", "text_fr": "Honnêtement, je n''ai pas eu beaucoup d''exposition aux outils de machine learning encore.", "next": "n7"}]}, "n7": {"speaker": "recruiter", "text": "That''s honest, thank you. Let''s do a quick coding-logic question — how would you reverse a string without a built-in function?", "text_fr": "C''est honnête, merci. Faisons une question de logique de code rapide — comment inverseriez-vous une chaîne sans fonction native ?", "choices": [{"text": "I''d iterate from the last character to the first and build a new string.", "text_fr": "J''itérerais du dernier caractère au premier et construirais une nouvelle chaîne.", "next": "n8"}, {"text": "I''d use two pointers, swapping characters from both ends toward the middle.", "text_fr": "J''utiliserais deux pointeurs, échangeant les caractères des deux extrémités vers le milieu.", "next": "n8"}]}, "n8": {"speaker": "recruiter", "text": "Great, that''s a solid approach. Do you have any questions for me at this point?", "text_fr": "Super, c''est une bonne approche. Vous avez des questions pour moi à ce stade ?", "choices": [{"text": "Yes, what does the onboarding process typically look like?", "text_fr": "Oui, à quoi ressemble le processus d''intégration typiquement ?", "next": "n9"}, {"text": "What technologies does the team currently use day-to-day?", "text_fr": "Quelles technologies l''équipe utilise-t-elle au quotidien ?", "next": "n9"}]}, "n9": {"speaker": "recruiter", "text": "Good question, let me walk you through that.", "text_fr": "Bonne question, laissez-moi vous expliquer ça.", "choices": [{"text": "Thank you, this has been a really thorough conversation.", "text_fr": "Merci, ça a été une conversation vraiment approfondie.", "next": "end_strong"}]}, "end_strong": {"speaker": "recruiter", "text": "It really has. You handled both the technical and behavioral parts well.", "text_fr": "C''est vrai. Vous avez bien géré à la fois les parties techniques et comportementales.", "end": true, "ending_label": "Entretien technique complet réussi 💻✅"}}}'::jsonb, is_playable = true
where title = 'Un entretien technique complet'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
